package com.clavis.reader;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.nio.charset.StandardCharsets;
final class FeedChecks {
 static int checks;static void check(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
 static FeedStore.Feed parse(String value)throws Exception{return FeedStore.parse(new ByteArrayInputStream(value.getBytes(StandardCharsets.UTF_8)),"https://example.com/feeds/main.xml");}
 static boolean find(View view,String text){if(view instanceof TextView&&((TextView)view).getText().toString().equals(text))return true;if(text.equals(view.getContentDescription()))return true;if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)if(find(((ViewGroup)view).getChildAt(i),text))return true;return false;}
 static String network(Instrumentation test)throws Exception{FeedStore.Feed large=FeedStore.download("https://feeds.simplecast.com/54nAGcIl","Podcasts");check(large.items.size()==300,"Large podcast feed streams only recent entries");org.json.JSONObject search=new org.json.JSONObject(new String(FeedStore.fetch("https://itunes.apple.com/search?media=podcast&entity=podcast&limit=5&term=planet%20money",2*1024*1024),StandardCharsets.UTF_8));check(search.getJSONArray("results").length()>0,"Online podcast source search");FeedStore.Feed feed=FeedStore.download("https://feeds.npr.org/510289/podcast.xml","Podcasts");check(!feed.items.isEmpty(),"Live podcast RSS entries");FeedStore.Item episode=null;for(FeedStore.Item item:feed.items)if(!item.audio.isEmpty()){episode=item;break;}check(episode!=null,"Live audio enclosure");android.media.MediaPlayer player=new android.media.MediaPlayer();java.util.concurrent.CountDownLatch prepared=new java.util.concurrent.CountDownLatch(1);final boolean[] ready={false};try{player.setOnPreparedListener(p->{ready[0]=true;prepared.countDown();});player.setOnErrorListener((p,w,e)->{prepared.countDown();return true;});player.setDataSource(test.getTargetContext(),android.net.Uri.parse(episode.audio));player.prepareAsync();check(prepared.await(45,java.util.concurrent.TimeUnit.SECONDS)&&ready[0],"Podcast stream prepares over HTTPS");check(player.getDuration()>0,"Podcast streaming duration");if(!episode.image.isEmpty())check(FeedStore.image(test.getTargetContext(),episode.image).length()>0,"Live podcast artwork cache");return "Live RSS, podcast streaming preparation, duration and artwork checks passed\n";}finally{player.release();}}
 static void artwork(Instrumentation test)throws Exception{
  android.content.Context context=test.getTargetContext();String base="https://example.invalid/audivo-check-"+System.nanoTime();String visible=base+"-visible.png",below=base+"-below.png";java.util.ArrayList<File> files=new java.util.ArrayList<>();
  for(String url:new String[]{visible,below}){StringBuilder hash=new StringBuilder();for(byte b:java.security.MessageDigest.getInstance("SHA-256").digest(url.getBytes(StandardCharsets.UTF_8)))hash.append(String.format(java.util.Locale.US,"%02x",b&255));File dir=new File(context.getCacheDir(),"rss-artwork");dir.mkdirs();File file=new File(dir,hash+".img");android.graphics.Bitmap bitmap=android.graphics.Bitmap.createBitmap(24,24,android.graphics.Bitmap.Config.ARGB_8888);bitmap.eraseColor(android.graphics.Color.RED);try(OutputStream out=new FileOutputStream(file)){bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}bitmap.recycle();files.add(file);}
  MainActivity activity=(MainActivity)test.startActivitySync(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ImageView[] images=new ImageView[3];try{test.runOnMainSync(()->{activity.screen="News";activity.shell("Artwork check");for(int n=0;n<3;n++){if(n==2)activity.space(activity.body,5000);images[n]=new ImageView(activity);activity.body.addView(images[n],new LinearLayout.LayoutParams(activity.dp(62),activity.dp(62)));FeedArtwork.bind(activity,images[n],n==2?below:visible);}});
   for(int wait=0;wait<100;wait++){final boolean[] ready={false};test.runOnMainSync(()->ready[0]=images[0].getDrawable()!=null&&images[1].getDrawable()!=null);if(ready[0])break;Thread.sleep(50);}
   test.runOnMainSync(()->{check(images[0].getDrawable()!=null&&images[1].getDrawable()!=null,"Visible artwork loads from disk");check(images[2].getDrawable()==null,"Offscreen artwork waits until visible");android.graphics.Bitmap first=((android.graphics.drawable.BitmapDrawable)images[0].getDrawable()).getBitmap(),second=((android.graphics.drawable.BitmapDrawable)images[1].getDrawable()).getBitmap();check(first==second,"Repeated artwork shares a decoded bitmap");ImageView cached=new ImageView(activity);FeedArtwork.bind(activity,cached,visible);check(cached.getDrawable()!=null,"Memory cache is immediate before attachment");((ScrollView)activity.root.getChildAt(1)).fullScroll(View.FOCUS_DOWN);});
   for(int wait=0;wait<100;wait++){final boolean[] ready={false};test.runOnMainSync(()->ready[0]=images[2].getDrawable()!=null);if(ready[0])break;Thread.sleep(50);}test.runOnMainSync(()->check(images[2].getDrawable()!=null,"Scrolling loads newly visible artwork"));
  }finally{test.runOnMainSync(activity::finish);for(File file:files)file.delete();}
  ArticleActivity article=(ArticleActivity)test.startActivitySync(new Intent(context,ArticleActivity.class).putExtra("url","https://example.com/").putExtra("title","Article check").putExtra("summary","Saved article text").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));try{test.runOnMainSync(()->{check(article.articleBody!=null,"Article uses native text and image container");check(article.source.equals("https://example.com/"),"Article source retained");check(find(article.bar,"Open website in browser"),"External website option is in top bar");});}finally{test.runOnMainSync(article::finish);}
 }
 static String run(Instrumentation test)throws Exception{checks=0;
  FeedStore.Feed rss=parse("<rss version='2.0' xmlns:itunes='http://www.itunes.com/dtds/podcast-1.0.dtd' xmlns:media='http://search.yahoo.com/mrss/' xmlns:content='http://purl.org/rss/1.0/modules/content/'><channel><title>Example Show</title><image><url>/show.jpg</url></image><item><guid>episode-1</guid><title>One &amp; Two</title><link>/episodes/one</link><description><![CDATA[<p>A short summary.</p>]]></description><content:encoded><![CDATA[<p>The complete article with punctuation, and more words.</p>]]></content:encoded><enclosure url='/one.mp3?download=1' type='audio/mpeg'/><itunes:duration>01:02:03</itunes:duration><media:thumbnail url='/episode.jpg'/><pubDate>Fri, 16 Oct 2026 10:00:00 GMT</pubDate></item><item><guid>episode-1</guid><title>Duplicate</title></item><item><title>Fallback cover</title><enclosure url='/two.m4a' type='audio/mp4'/></item></channel></rss>");
  check(rss.title.equals("Example Show"),"RSS channel title");check(rss.items.size()==2,"Deduplicated RSS entries");FeedStore.Item one=rss.items.get(0);check(one.title.equals("One & Two"),"Entities decoded");check(one.audio.equals("https://example.com/one.mp3?download=1"),"Audio enclosure URL");check(one.duration==3723000,"Podcast HH:MM:SS duration");check(one.image.equals("https://example.com/episode.jpg"),"Episode artwork overrides show cover");check(rss.items.get(1).image.equals("https://example.com/show.jpg"),"Show artwork fallback");check(one.description.contains("complete article"),"Full content preferred to summary");check(one.link.equals("https://example.com/episodes/one"),"Relative article URL");check(one.date.contains("2026"),"Publication date");
  FeedStore.Feed atom=parse("<feed xmlns='http://www.w3.org/2005/Atom'><title>Journal</title><entry><id>doi:sample</id><title>Research paper</title><link href='../article' rel='alternate'/><link href='https://example.com/paper.pdf' rel='enclosure' type='application/pdf'/><summary>Short abstract</summary><content type='html'>&lt;p&gt;A full abstract with details.&lt;/p&gt;</content><published>2026-10-16</published></entry></feed>");
  check(atom.title.equals("Journal"),"Atom feed title");check(atom.items.size()==1,"Atom entry");check(atom.items.get(0).document.endsWith("paper.pdf"),"Journal PDF enclosure");check(atom.items.get(0).link.equals("https://example.com/article"),"Atom alternate link");check(atom.items.get(0).description.contains("full abstract"),"Atom content");
  FeedStore.Feed news=parse("<rss><channel><title>News</title><item><title>Story</title><description><![CDATA[<img src='/story.png'><p>Story text</p>]]></description></item></channel></rss>");check(news.items.get(0).image.equals("https://example.com/story.png"),"Description artwork");check(FeedScreens.plain(news.items.get(0).description).contains("Story text"),"Article HTML renders as text");
  check(FeedStore.duration("90")==90000,"Seconds duration");check(FeedStore.duration("12:30")==750000,"Minutes duration");check(FeedStore.web("javascript:alert(1)").isEmpty(),"Reject non-web URLs");boolean rejected=false;try{parse("<html><body>Not a feed</body></html>");}catch(IOException expected){rejected=true;}check(rejected,"Reject ordinary website HTML");
  StringBuilder large=new StringBuilder("<rss><channel><title>Bounded</title>");for(int i=0;i<350;i++)large.append("<item><guid>").append(i).append("</guid><title>Entry</title></item>");large.append("</channel></rss>");check(parse(large.toString()).items.size()==300,"Bounded cached entries");
  Book podcast=new Book("https://example.com/episode.mp3","Episode fixture","Podcast");podcast.position=1234;podcast.duration=10000;podcast.coverUri="https://example.com/cover.jpg";Book restored=new Book(podcast.json());check(restored.isAudio()&&restored.author.equals("Podcast"),"Distinct podcast media type persists");check(restored.position==1234,"Episode position persists");check(BookProgress.label(restored).endsWith("listened"),"Podcast audio progress");check(new Book("audio","Book","Audio").isAudio(),"Audiobook compatibility");
  int total=0;java.util.HashMap<String,Integer> defaults=new java.util.HashMap<>();org.json.JSONArray catalog=FeedCatalog.catalog(test.getTargetContext());for(int n=0;n<catalog.length();n++){org.json.JSONObject source=catalog.getJSONObject(n);try(InputStream in=test.getTargetContext().getAssets().open(source.getString("asset"))){FeedStore.Feed fixture=FeedStore.parse(in,source.getString("url"));check(!fixture.items.isEmpty(),"Bundled source has entries: "+source.getString("title"));if(source.getString("kind").equals("Podcasts"))check(fixture.items.stream().anyMatch(item->!item.audio.isEmpty()),"Bundled podcast audio: "+source.getString("title"));}if(source.optBoolean("preload")){String kind=source.getString("kind");defaults.put(kind,defaults.getOrDefault(kind,0)+1);total++;}}check(total==30,"Thirty preloaded sources");for(String kind:new String[]{"News","Podcasts","Journals"})check(defaults.getOrDefault(kind,0)==10,"Ten defaults for "+kind);
  MainActivity activity=(MainActivity)test.startActivitySync(new Intent(test.getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));try{test.runOnMainSync(()->{for(String category:new String[]{"Ebooks","PDF Books","Audio Books","News","Podcasts","Journals"})check(find(activity.root,category),"Home category "+category);check(find(activity.mainFrame,"Audiobooks")&&find(activity.mainFrame,"Podcasts"),"Separate player buttons in bottom pill");for(String kind:new String[]{"News","Podcasts","Journals"}){activity.library(kind);check(find(activity.root,"Add RSS feed"),kind+" feed subscription action");check(find(activity.bar,"Browse "+kind+" sources"),kind+" top-bar source browser");}Book fixture=new Book("fixture:episode","Podcast fixture","Podcast");activity.nowPlaying(fixture);check(activity.screen.equals("PodcastPlayer"),"Distinct podcast player screen");check(find(activity.root,"Podcast player"),"Podcast player title");check(find(activity.root,"Episodes"),"Episode list control");check(find(activity.root,"Previous episode")&&find(activity.root,"Next episode"),"Episode navigation controls");activity.home();});}finally{test.runOnMainSync(activity::finish);}artwork(test);return checks+" RSS, podcast, artwork and article checks passed\n";
 }
}
